nodes.command:
node -e "
const fs = require('fs');
const path = require('path');

const animDir = '${inputs.project_root}/assets/images/animations/${inputs.character_id || inputs.animation_type}';
const spritesheetPath = '${inputs.project_root}/assets/images/spritesheets/${inputs.character_id || inputs.animation_type}_${inputs.animation_name}.png';

console.log('Animation validation:');
console.log('  Type:', '${inputs.animation_type}');
console.log('  Name:', '${inputs.animation_name}');
console.log('  Frames:', ${inputs.frame_count});
console.log('  FPS:', ${inputs.frame_rate});
console.log('  Output Mode:', '${inputs.output_mode}');
console.log('  Format: PNG');

if ('${inputs.output_mode}' === 'spritesheet' && fs.existsSync(spritesheetPath)) {
  const stats = fs.statSync(spritesheetPath);
  console.log('  Spritesheet:', spritesheetPath, '(' + stats.size + ' bytes)');
} else {
  console.log('  Assets not yet created (placeholder mode)');
}
"

node -e "
const fs = require('fs');
const path = '${inputs.project_root}/src/data/asset-registry.json';
let registry = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path)) : { backgrounds: {}, characters: {}, objects: {}, animations: {} };

registry.animations = registry.animations || {};
const animKey = '${inputs.character_id || inputs.animation_type}_${inputs.animation_name}';
registry.animations[animKey] = {
  type: '${inputs.animation_type}',
  name: '${inputs.animation_name}',
  character_id: '${inputs.character_id}' || null,
  spritesheet: '${inputs.output_mode}' === 'spritesheet' ? 'assets/images/spritesheets/' + animKey + '.png' : null,
  frames: ${inputs.frame_count},
  frame_rate: ${inputs.frame_rate},
  format: 'PNG',
  asset_mode: 'production',
  updated_at: new Date().toISOString()
};

fs.writeFileSync(path, JSON.stringify(registry, null, 2));
console.log('Asset registry updated for animation:', animKey);
"

